913	static int aivlog_cloud_read_asset(uint32_t session_id,
914	                                   unsigned int sequence,
915	                                   FAR uint8_t **body)
916	{
917	  struct stat st;
918	  char path[AIVLOG_CLOUD_PATH_SIZE];
919	  FAR uint8_t *buffer;
920	  size_t offset = 0;
921	  int fd;
922	
923	  if (aivlog_cloud_asset_path(session_id, sequence, false,
924	                              path, sizeof(path)) < 0)
925	    {
926	      return ERROR;
927	    }
928	
929	  fd = open(path, O_RDONLY);
930	  if (fd < 0)
931	    {
932	      return ERROR;
933	    }
934	
935	  if (fstat(fd, &st) < 0 || !S_ISREG(st.st_mode) ||
936	      st.st_size != CAMERA_GALLERY_BMP_SIZE)
937	    {
938	      close(fd);
939	      errno = EINVAL;
940	      return ERROR;
941	    }
942	
943	  buffer = malloc(CAMERA_GALLERY_BMP_SIZE);
944	  if (buffer == NULL)
945	    {
946	      close(fd);
947	      errno = ENOMEM;
948	      return ERROR;
949	    }
950	
951	  while (offset < CAMERA_GALLERY_BMP_SIZE)
952	    {
953	      size_t chunk = CAMERA_GALLERY_BMP_SIZE - offset;
954	      ssize_t nread;
955	
956	      if (chunk > sizeof(g_aivlog_cloud_sd_io))
957	        {
958	          chunk = sizeof(g_aivlog_cloud_sd_io);
959	        }
960	
961	      nread = read(fd, g_aivlog_cloud_sd_io, chunk);
962	      if (nread < 0 && errno == EINTR)
963	        {
964	          continue;
965	        }
966	
967	      if (nread <= 0)
968	        {
969	          int saved_errno = nread == 0 ? EIO : errno;
970	          close(fd);
971	          free(buffer);
972	          errno = saved_errno;
973	          return ERROR;
974	        }
975	
976	      memcpy(buffer + offset, g_aivlog_cloud_sd_io, (size_t)nread);
977	      offset += (size_t)nread;
978	    }
979	
980	  close(fd);
981	  *body = buffer;
982	  return OK;
983	}
